## What the validation tools just showed you

I ran four checks against the two toolchains. The results are the whole security lesson in miniature:

| Input | Validator verdict | Meaning |
|---|---|---|
| `2 + 3 * (4 - 1) / 2` | ✅ valid, AST parsed, evaluates to `6.5` | Legitimate arithmetic passes cleanly |
| `__import__('os').system('rm -rf /')` | ❌ `Unexpected character '_'` | Rejected at the **lexer**, never reaches an evaluator |
| `(1).__class__.__bases__[0].__subclasses__()` | ❌ `Unexpected character '_'` (×2) | Sandbox-escape chains die at the same gate |

The key architectural takeaway: **`_` and `.` are outside the grammar, so attribute access and dunder traversal are not "blocked" — they are unrepresentable.** That is deny-by-default working correctly. A blocklist that tries to strip `__import__`, `eval`, `os`, `subprocess` will always lose; there are dozens of bypasses (`getattr`, f-string tricks, `().__class__`, encodings). An allowlist of node types cannot be talked around.

Now let me turn that principle into code you can ship.

---

## 1. Never call `eval()` — parse to an AST and walk an allowlist

The core pattern, production-shaped:

```python
# safe_eval.py
import ast
import math
import operator
from dataclasses import dataclass

MAX_EXPR_LEN = 256      # DoS: huge strings
MAX_NODES = 100         # DoS: pathological tree width
MAX_DEPTH = 12          # DoS: deep recursion -> RecursionError
MAX_EXPONENT = 100      # DoS: 9**9**9**9 hangs the CPU
MAX_RESULT_BITS = 4096  # DoS: giant integers


class UnsafeExpression(ValueError):
    """Expression failed validation. Message is safe to log, not to return."""


_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_CONSTANTS = {"pi": math.pi, "e": math.e, "tau": math.tau}

_FUNCS = {
    "abs": abs, "round": round, "min": min, "max": max,
    "sqrt": math.sqrt, "exp": math.exp, "log": math.log,
    "log2": math.log2, "log10": math.log10, "fabs": math.fabs,
    "floor": math.floor, "ceil": math.ceil, "trunc": math.trunc,
    "sin": math.sin, "cos": math.cos, "tan": math.tan,
    "asin": math.asin, "acos": math.acos, "atan": math.atan,
    "degrees": math.degrees, "radians": math.radians, "hypot": math.hypot,
}
```

### The validator — an explicit node allowlist

```python
class SafeEvaluator:
    def validate(self, expr: str) -> ast.Expression:
        if not isinstance(expr, str) or not expr.strip():
            raise UnsafeExpression("expression must be a non-empty string")
        if len(expr) > MAX_EXPR_LEN:
            raise UnsafeExpression("expression exceeds length limit")

        try:
            tree = ast.parse(expr.strip(), mode="eval")
        except (SyntaxError, ValueError, MemoryError) as exc:
            raise UnsafeExpression("malformed expression") from exc

        self._walk(tree)
        return tree

    def _walk(self, tree: ast.Expression) -> None:
        count, stack = 0, [(tree, 0)]
        while stack:
            node, depth = stack.pop()
            count += 1
            if count > MAX_NODES:
                raise UnsafeExpression("expression too complex")
            if depth > MAX_DEPTH:
                raise UnsafeExpression("expression nested too deeply")
            self._check_node(node)
            stack.extend((child, depth + 1) for child in ast.iter_child_nodes(node))

    def _check_node(self, node: ast.AST) -> None:
        # Every branch is an ALLOW decision. Anything unmatched falls through to reject.
        if isinstance(node, ast.Expression):
            return
        if isinstance(node, ast.Constant):
            # bool is a subclass of int -> explicitly exclude it
            if isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
                return
            raise UnsafeExpression("only numeric literals are allowed")
        if isinstance(node, ast.BinOp):
            if type(node.op) not in _BINOPS:
                raise UnsafeExpression("operator not permitted")
            return
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, (ast.UAdd, ast.USub)):
                return
            raise UnsafeExpression("unary operator not permitted")
        if isinstance(node, ast.Name):
            if node.id in _FUNCS or node.id in _CONSTANTS:
                return
            raise UnsafeExpression("unknown identifier")
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in _FUNCS:
                raise UnsafeExpression("call target not permitted")
            if node.keywords:
                raise UnsafeExpression("keyword arguments not permitted")
            return
        # Attribute, Subscript, Lambda, Starred, NamedExpr, JoinedStr,
        # comparisons, comprehensions, etc. all land here.
        raise UnsafeExpression(f"syntax not permitted: {type(node).__name__}")
```

### Evaluation with resource guards

```python
    def evaluate(self, expr: str) -> float | int:
        tree = self.validate(expr)
        try:
            value = self._eval(tree.body)
        except (ZeroDivisionError, OverflowError, TypeError, ValueError) as exc:
            raise UnsafeExpression("invalid mathematical operation") from exc

        if isinstance(value, int) and value.bit_length() > MAX_RESULT_BITS:
            raise UnsafeExpression("result too large")
        if isinstance(value, float) and not math.isfinite(value):
            raise UnsafeExpression("result not finite")
        return value

    def _eval(self, node: ast.AST):
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            return _CONSTANTS[node.id]
        if isinstance(node, ast.UnaryOp):
            operand = self._eval(node.operand)
            return +operand if isinstance(node.op, ast.UAdd) else -operand
        if isinstance(node, ast.BinOp):
            left, right = self._eval(node.left), self._eval(node.right)
            if isinstance(node.op, ast.Pow):
                return self._safe_pow(left, right)
            return _BINOPS[type(node.op)](left, right)
        if isinstance(node, ast.Call):
            args = [self._eval(a) for a in node.args]
            return _FUNCS[node.func.id](*args)
        raise UnsafeExpression(f"unsupported node: {type(node).__name__}")

    @staticmethod
    def _safe_pow(base, exp):
        if abs(exp) > MAX_EXPONENT:
            raise UnsafeExpression("exponent too large")
        if isinstance(base, int) and isinstance(exp, int) and exp > 0:
            if base.bit_length() * exp > MAX_RESULT_BITS:
                raise UnsafeExpression("result too large")
        return base ** exp
```

Note that `validate()` and `evaluate()` are separate on purpose — you can dry-run validation at the API boundary and only execute after auth, rate-limit, and audit checks pass.

